ass="pppoe-modal-backdrop" data-close-modal></div><div class="pppoe-modal-dialog"><div class="pppoe-modal-header"><div><h2 id="userModalTitle">Tambah User PPPoE</h2><small>Buat account baru langsung di MikroTik</small></div><button type="button" class="modal-close" data-close-modal>×</button></div><form id="userForm"><input type="hidden" name="id"><div class="form-grid"><label>Username<input class="form-control" name="name" maxlength="64" required></label><label>Password<input class="form-control" name="password" maxlength="128" autocomplete="new-password"></label><label>Service<select class="form-control" name="service"><option value="pppoe">PPPoE</option><option value="any">Any</option></select></label><label>Profile<select class="form-control" name="profile" id="profileSelect"><option value="default">default</option></select></label><label>Local Address<input class="form-control" name="local_address" maxlength="64"></label><label>Remote Address<input class="form-control" name="remote_address" maxlength="64"></label><label class="form-full">Comment<input class="form-control" name="comment" maxlength="128"></label></div><div id="formMessage" class="alert-app pppoe-message" hidden></div><div class="modal-actions"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button type="submit" class="btn btn-primary" id="saveUserBtn">Simpan User</button></div></form></div></div><div class="pppoe-modal" id="profileModal" hidden><div class="pppoe-modal-backdrop" data-close-profile></div><div class="pppoe-modal-dialog"><div class="pppoe-modal-header"><div><h2 id="profileModalTitle">Tambah Profile PPPoE</h2><small>Atur bandwidth dan parameter profile MikroTik</small></div><button type="button" class="modal-close" data-close-profile>×</button></div><form id="profileForm"><input type="hidden" name="id"><div class="form-grid"><label>Nama Profile<input class="form-control" name="name" maxlength="64" required></label><label>Rate Limit<input class="form-control" name="rate_limit" placeholder="10M/10M"></label><label>Local Address<input class="form-control" name="local_address"></label><label>Remote Address<input class="form-control" name="remote_address"></label><label>Only One<select class="form-control" name="only_one"><option value="">Default</option><option value="yes">Yes</option><option value="no">No</option></select></label><label>Comment<input class="form-control" name="comment" maxlength="128"></label></div><div id="profileFormMessage" class="alert-app pppoe-message" hidden></div><div class="modal-actions"><button type="button" class="btn btn-secondary" data-close-profile>Batal</button><button type="submit" class="btn btn-primary" id="saveProfileBtn">Simpan Profile</button></div></form></div></div></main><script src="../assets/js/pppoe_stats_bus.js?v=4"></script><script src="../assets/js/pppoe_pro.js?v=3"></script><script src="../assets/js/pppoe_management.js?v=9"></script><script src="../assets/js/pppoe_analytics.js?v=4"></script><script src="../assets/js/pppoe_bandwidth.js?v=4"></script><script src="../assets/js/pppoe_dashboard_pro.js?v=4"></script><script src="../assets/js/pppoe_bandwidth_alarm.js?v=6"></script><script src="../assets/js/alarm_notification.js?v=2"></script><script>(function(){const api='../api/pppoe.php',$=id=>document.getElementById(id);async function get(a){const r=await fetch(api+'?action='+encodeURIComponent(a)+'&t='+Date.now(),{cache:'no-store'});const d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Request gagal');return d}async function refresh(){try{const[a,s,p]=await Promise.all([get('active'),get('secrets'),get('profiles')]);window.pppoeData={active:a.users||[],secrets:s.secrets||[],profiles:p.profiles||[]};$('activeCount').textContent=window.pppoeData.active.length;$('secretCount').textContent=window.pppoeData.secrets.length;$('profileCount').textContent=window.pppoeData.profiles.length;$('connectionStatus').textContent='● ONLINE';$('connectionStatus').className='badge-status status-online';$('lastUpdate').textContent='Last update: '+new Date().toLocaleTimeString('id-ID');const b=$('messageBox');b.hidden=true;b.textContent='';}catch(e){$('connectionStatus').textContent='● OFFLINE';$('connectionStatus').className='badge-status status-offline';const b=$('messageBox');b.textContent=e.message;b.hidden=false;b.classList.add('error')}}window.pppoeRefresh=refresh;$('refreshBtn').addEventListener('click',refresh);refresh();setInterval(()=>{if(document.visibilityState==='visible')refresh()},10000)})();</script></body></html>
